INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('gamehub-gaming-platform','Multiplayer gaming hub',NULL,'Online gaming operator · India','Custom software','Gaming','Players log in with mobile number and password, hold one virtual-coin wallet and play 14 games from one mobile app: Teen Patti, Rummy, Poker, Ludo, Chess, Dragon Tiger, Andar Bahar, Lucky 7, Roulette, Blackjack, Plinko, Stock Market and more, with private tables by invite code and labelled bot opponents. Super Admin, Admin and Agent roles run a console for creating accounts and coins down a hierarchy, game config, RTP, payment requests, outcome control, win and IP alerts and an audit log.','Main workflow: Agent creates a player and passes on coins → Player logs in and picks a game or lobby → Server deals, times turns and settles each round → Wallet ledger and game history update → Admin reviews reports, alerts and payment requests','["Player app: splash, OTP-style login, home, game lobbies, tables, wallet with coin history, account and limits", "Server games: Teen Patti, 13-card Rummy, Roulette, Blackjack, Plinko and casino rounds run in Supabase", "Private tables: creator sets boot or entry amount and shares an invite code, no bots", "Admin console: role-based dashboard, network hierarchy, bots, game config, RTP, outcome control", "Admin alerts: payment requests, win alerts, IP alerts, round lookup, private-table reports, support", "Cricket and sports: live matches and odds feeds with results view in admin"]'::jsonb,'["Next.js 16", "React 19", "Supabase (Postgres, Auth, Realtime)", "Tailwind 4", "Row-level security"]'::jsonb,'https://gameplaydrive.vercel.app','[]'::jsonb,'live',false,false,310) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
