INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('matka-market-app','Matka market app + admin panel',NULL,'Online gaming operator · India','Mobile apps','Gaming','Players log in with mobile and password, pick a market (28 main markets plus Starline and Galidesawar), place Single Ank, Jodi, Pana and Sangam bids through a review screen, add funds via UPI apps and withdraw to PhonePe, Google Pay, Paytm or a UPI ID. The admin declares results per market and session, sees every winning bid and payout before confirming, approves fund and withdrawal requests, manages users, rates, market off-days, notices and reports. Ships as an Android app via Capacitor with switchable branding.','Main workflow: Player registers and logs in → Picks a market and bet type, enters amounts and submits via the review screen → Adds funds via UPI (auto or admin-approved request) → Admin declares the result; winnings credit wallets instantly → Player withdraws; admin approves or rejects with refund','["Player Home: market cards with open/close times and holiday flag, Starline and Galidesawar, golden ank, banners", "Play: bet type picker, date and session, per-number amounts, Sangam rows, review screen with wallet before/after", "Funds: add fund via PhonePe / Google Pay / Paytm / UPI deep links or request, withdraw with method and minimums, history", "Admin Declare: date + game + session, pana entry with auto ank, Show Winner list with payouts, confirm-by-retype, undo", "Admin Wallet & Users: add-fund and withdrawal queues with approve/reject, user accounts, revert tool, reports", "Admin Settings: game rates (value 1 -> value 2), market off-days, auto-UPI toggle, app name, notices, prediction"]'::jsonb,'["Next.js 16", "React 19", "Tailwind 4", "Capacitor (Android)", "Supabase schema", "localStorage demo store"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,false,470) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('nidhi-banking-software','Nidhi company banking software','Grihsevak Nidhi','Nidhi (cooperative finance) company · India','ERP / CRM','Finance','Branch staff register members, open FD / RD / DRD / MIS deposits and loans, record daily collections and EMIs, pay out maturities and print passbooks, receipts, FD certificates and loan agreements as PDF. The owner gets multi-branch dashboards, an accounting module with vouchers, ledger and trial balance, expenses, staff logins with per-module permissions, reports, SMS and a bulk import tool. The same web app is wrapped as an Android app.','Main workflow: Staff registers a member with KYC → Opens a deposit or loan; schedule and passbook entries are generated → Daily collection / EMI payments are recorded → Maturity page pays out and closes the account → Passbook, receipt and certificate PDFs printed; accounting and reports update','["Members: searchable member table, profile with tabs for deposits, loans, passbook and documents, edit and KYC upload", "Deposits & Loans: deposit form with maturity calc, loan form with EMI calculator and repayment schedule, edit flows", "Collection: deposit-collection and loan-collection screens for daily entries, withdrawals and maturity payouts", "Passbook: per-member passbook table, print view and settings; PDF receipts, FD certificates and loan agreements", "Accounting: vouchers, ledger and trial balance; expenses page; reports with export and date range", "Admin: branches, staff with permission editor and login management, settings, import from ledger sheets, SMS API"]'::jsonb,'["Next.js 16", "React 19", "Supabase", "Radix UI / shadcn", "pdf-lib", "Capacitor (Android)"]'::jsonb,'https://cooperative-crm-theta.vercel.app','[]'::jsonb,'live',false,true,480) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
