INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('textile-donation-certificates','Textile donation certificate system','JIJA Textile Recovery Facility – Panvel (JIJA Group)','Textile recycling facility · Panvel','Custom software','Recycling / CSR','Donors scan a camp QR code, fill in their name, donation weight and duration, and instantly receive a stamped PDF certificate with a unique year-wise ID (JTRF-2026-00001) that they can share on WhatsApp or Facebook; anyone can verify a certificate by scanning its QR. The admin sees donation stats and charts, manages camps and printable camp posters, toggles certificate status, exports data and gets automatic birthday wishes for donors. A parallel Google Form + Sheets + Apps Script version does the same with zero hosting.','Main workflow: Donor scans camp QR and submits the donation form → Unique certificate ID assigned and PDF certificate generated with stamp and QR → Donor shares on WhatsApp / Facebook with a preview card → Anyone verifies the certificate at /verify → Admin reviews donations, camps, exports and birthday wishes','["Donate: QR-linked form with donor type, weight, items, footwear, duration, camp and consent; validation", "Certificate: printable A4 certificate with stamp, signatory and QR; OpenGraph image for link previews", "Verify: public verification page showing name, weight, date and ID without exposing mobile, email or DOB", "Admin dashboard: totals and charts by camp, society and month; donations list with status toggle and CSV export", "Admin camps: camp list and per-camp printable QR poster; birthdays page with daily email and WhatsApp wish links", "Apps Script variant: Google Form -> Sheet -> Slides certificate -> Drive PDF -> email, dashboard sheet"]'::jsonb,'["Next.js 16", "Supabase", "jsPDF", "qrcode", "Netlify Functions", "Google Apps Script"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,490) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('ashok-sweets-store','Online sweets store','Nakhye''s Ashok Sweets (M/S Nakhye Foods LLP)','Indian sweets brand · Maharashtra','E-commerce','Food & beverage','Customers browse hot-selling and occasion-led gift sweets, pick quantities, add to cart or buy now, and complete address and payment through Shiprocket Checkout; an order-success page re-verifies payment with the server. The store admin signs in to add or remove products, manage availability and inventory, create coupons and track orders. Product, inventory, coupon and order APIs are exposed for Shiprocket catalogue sync.','Main workflow: Customer discovers sweets or gift boxes → Chooses quantity and adds to cart → Checkout posts the cart for an HMAC-signed Shiprocket token → Shiprocket collects address, coupon and payment → Order status re-checked on return; admin tracks orders','["Storefront: discover, all sweets, product detail with quantity options, gifting boxes and bulk enquiry", "Cart & checkout: persistent cart, Shiprocket headless checkout token, order-success verification page", "Customer account: sign-in and profile with order activity; policies and support pages", "Store admin: role-gated login, products, inventory, coupons and orders screens", "Catalogue APIs: products, collections, coupons and order-status endpoints for Shiprocket sync", "Supabase schema: roles, products, inventory, coupons, orders and order lines with RLS"]'::jsonb,'["React 19", "Vite", "TypeScript", "Supabase", "Shiprocket Checkout", "Netlify Functions"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,500) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('dcw-education-superapp','Education & jobs super-app','DCW','Education consultancy · Patna','Custom software','Education','Students browse three verticals in a mobile-style shell — distance universities, colleges and jobs — search and filter, compare fees side by side, run a board-selection quiz, a NEET rank predictor and a resume builder, then apply or request counselling with OTP verification. The admin manages the institution catalogue with an add wizard, courses, fees and proof documents, boards, jobs with employer proof, applications with a candidate drawer, leads, students, reviews, WhatsApp templates and settings. Leads and application status sync to a CRM through webhooks.','Main workflow: Student picks a vertical (distance / colleges / jobs) → Searches, filters and compares options → Uses a tool (board quiz, rank predictor, resume builder) → Submits an application or lead with OTP → Admin reviews applications and leads; CRM and WhatsApp webhooks update status','["Discovery: per-vertical home, listing with filters and sort, entity detail pages, saved items and compare tray", "Tools: board comparison quiz, NEET rank predictor, resume builder wizard, abroad-eligibility check", "Account: applications, saved, compare and automations screens; OTP send/verify and lead submission", "Admin catalogue: institution add wizard, course and fee editing, proof uploads and publish toggle", "Admin ops: jobs with employer proof, applications with candidate drawer, leads, students, boards, reviews", "Integrations: WhatsApp inbound webhook and templates page, CRM status webhook, sitemap and search API"]'::jsonb,'["Next.js", "React", "Tailwind 4", "JSON document store", "Route Handlers (REST API)"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,510) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('gamehub-multiplayer-games','Multiplayer gaming hub',NULL,'Online gaming operator · India','Custom software','Gaming','Players sign in with mobile and password and play 14 games — Teen Patti, Rummy (Points, Pool, Deals), Poker, Dragon Tiger, Andar Bahar, Lucky 7, Roulette, Blackjack, Plinko, Aviator, Ludo, Chess and Carrom — from one virtual-coin wallet, with labelled bots filling tables and private tables by invite code. Card and casino games are dealt and settled inside Supabase (Postgres functions + Realtime) so players only ever see their own cards. A role-based console lets the Super Admin create admins and agents, issue coins, configure game fees and timers and manage bots, while admins and agents manage their own downline and see an audit log.','Main workflow: Agent creates a player and transfers coins → Player logs in, picks a game and joins a lobby or private table → Server deals, times turns, plays bots and settles the round → Wallet ledger updates with bets, winnings and refunds → Admin console shows network, audit log and game config','["Player app: splash and login, home with game grid, lobbies by stake, landscape game stage, wallet and account", "Casino tables: Dragon Tiger, Andar Bahar, Lucky 7, Roulette, Plinko with chips, undo/rebet/double and last results", "Card games: Teen Patti (blind/seen, side show), Rummy with drop/declare, Poker, Blackjack with split/double", "Board games: Ludo with animated tokens, Chess with full rules vs computer, Carrom with physics", "Wallet: single coin balance, full ledger of bets/winnings/refunds, agent payment details, responsible-gaming limits", "Admin console: Super Admin / Admin / Agent roles, coin issuance, bot pool, game config, freeze accounts, audit log"]'::jsonb,'["Next.js 16", "React 19", "Tailwind 4", "Supabase (Postgres functions, Realtime)", "Node game server (Railway)"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,520) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('hotel-sales-command-center','Hotel sales & operations CRM',NULL,'Hotel group','ERP / CRM','Hospitality','Hotel sales and reception staff work a unified enquiry inbox across channels, reply from a conversation thread with a quote builder, move deals through a pipeline to confirmed booking and clear scheduled follow-ups. Automated replies are clearly labelled, and anything needing human judgement lands in an Exceptions queue with a decision panel. The owner gets a Command Center with revenue at risk, response leaderboard and channel mix, plus bookings day-book, availability matrix and floor map, pricing rules with approval floors, analytics, scheduled reports, team roles and automation settings per enquiry type.','Main workflow: Enquiry arrives in the Leads inbox from any channel → Staff or automation replies and sends a quote → Deal moves through the Pipeline to confirmed booking → Follow-ups run on schedule; edge cases go to Exceptions for a human decision → Command Center and reports show conversion, revenue and response times','["Leads: unified inbox with triage pane, conversation thread with labelled automated turns, composer and quote builder", "Pipeline & follow-ups: kanban board with conversion strip and lost-reason dialog; follow-up queue with toolbar", "Bookings & availability: day-book with booking drawer; inventory matrix, floor map, blocks, occupancy forecast", "Pricing & exceptions: rate cards, discount rules and simulator with authority panel; exception queue with decisions", "Command Center & analytics: metric strip, revenue at risk, activity feed; funnel, revenue, channel and response charts", "System: team roles and permission matrix, integrations, settings for policies, targets and automation modes"]'::jsonb,'["Next.js 16", "React 19", "Tailwind 4", "Zustand", "Recharts", "Radix UI"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,530) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
