INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('weddingmall-mobile-app','Wedding marketplace mobile app',NULL,'Wedding marketplace','Mobile apps','Weddings','Couples pick a city, browse and filter wedding vendors by category, open galleries, shortlist favourites on-device and send enquiries without creating an account; a built-in biodata maker produces a marriage biodata PDF from several templates. Vendors sign in by email to see their listing summary and incoming leads. The Android/iOS app runs on the same Supabase project as the WeddingMall website, so admin changes and enquiries stay in one place.','Main workflow: Couple selects a city → Explores vendors by category with filters and sort → Opens vendor detail and gallery, shortlists → Sends an enquiry via form, call or WhatsApp → Vendor signs in and sees the lead in their dashboard','["Couple screens: home, explore with search and filters, vendor detail with gallery lightbox, favourites, city selector", "Enquiry: enquiry form plus call / WhatsApp contact actions; leads land in the shared leads inbox", "Biodata maker: stepper form, photo picker, Classic / Floral / Minimal / Sacred / Themed templates, PDF export", "Vendor: email sign-in, password reset, dashboard with listing summary and leads list", "Content: blogs, careers, privacy and terms screens; onboarding tour and notifications badge", "Native: Capacitor Android and iOS shells with deep links, share, downloads and store listings"]'::jsonb,'["React 19", "Vite", "TanStack Query", "Supabase", "Capacitor (Android + iOS)", "@react-pdf/renderer"]'::jsonb,'https://weddingmall.vercel.app','[]'::jsonb,'live',false,true,550) ON CONFLICT ("slug") DO NOTHING;
