INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('swamitra-foundation-website','Foundation website with content admin','SWAMITRA Foundation','Legal-education NGO · India','Websites','Non-profit','Visitors explore the foundation''s programmes, training courses with registration, research centre, resource library with live search, news and events, policies and ways to get involved, in English and Hindi; on phones the site becomes an installable app shell with a bottom tab bar. Staff edit text, photos, programmes, news and policies at /admin and publish straight to the live site through Supabase, with every publish kept as a revision and the committed data file as a fallback.','Main workflow: Visitor opens the home page and picks a programme or training → Reads the detail page or searches the resource library → Registers for training or submits a get-involved / contact form → Staff edit content in /admin → Publish writes data.js to Supabase Storage; live site updates on next load','["Public pages: home, about, objectives, 10 programmes, 9 trainings with course detail, research, resources, news", "Resource centre: live search and filters; download centre, publications, multimedia library", "Get involved: volunteer, partner, donate, CSR, internship, careers, membership pages with forms", "Legal: 13 policies rendered from one data file; governance, transparency and compliance pages", "Mobile app shell: sticky app bar, bottom tabs, drawer, safe-area padding, PWA manifest; Hindi mirror pages", "Admin: content editor with autosave draft, image uploads, revisions and one-click publish via Supabase"]'::jsonb,'["HTML/CSS/JavaScript", "PWA manifest", "Supabase (admin publishing)", "Netlify"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,560) ON CONFLICT ("slug") DO NOTHING;
