INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('maheshwari-plot-sales-crm','Plot sales & associate CRM','Maheshwari Group','Plot developer · Bihar','ERP / CRM','Real estate','Telecallers and marketing managers log leads, follow up and check live plot availability on an interactive plot map before reserving; associates bring buyers and earn commissions through a downline. The owner manages properties and plot units with images, sales and deal fields, commission payouts, telecallers, marketing managers with profile documents and settings from a dashboard with charts. Role-based views come from Supabase row-level security, and the app is wrapped as an Android app.','Main workflow: Telecaller adds a lead and follow-ups → Checks plot availability on the plot map → Plot reserved and sale recorded with deal fields → Associate commission calculated on the sale → Owner reviews dashboard, sales and commissions','["Dashboard: role-aware KPIs, lead and sales charts, plot status counts (available / reserved / sold)", "Leads: lead list with statuses including NR, telecaller assignment and follow-ups", "Properties: property cards and table, image upload, plot units with status and an interactive PlotMap", "Sales & commissions: sale records with plot deal fields, associate commission tracking", "Team: associates with downline, telecallers, marketing managers with profile and staff documents", "Auth & settings: login and registration, settings page, Android wrapper via Capacitor"]'::jsonb,'["Next.js 16", "React 19", "Supabase", "shadcn/ui", "Recharts", "Capacitor (Android)"]'::jsonb,'https://mahesewarigroup.vercel.app','[]'::jsonb,'live',false,true,580) ON CONFLICT ("slug") DO NOTHING;
