INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('balaji-electronics-store','Electronics store with wholesale mode','Balaji Electronic','Electronics retailer · Pune','E-commerce','Retail','Shoppers pass a phone-number lead gate, browse a 500-SKU catalogue across 18 categories with search (Ctrl/Cmd+K), filters and scroll rails, switch between retail and wholesale pricing, save products, manage a persistent cart and run a demo checkout or payment-link flow. QR codes encode a product, category or wholesale view so printed shelf tags open the right page and tag the lead as a scan; a site-guide bot helps on the way. The admin panel shows captured leads, visits, carts and orders, and products can print a spec sheet.','Main workflow: Customer scans a shelf QR or opens the site and enters a phone number → Browses or searches the catalogue in retail or wholesale mode → Saves products and builds a cart → Checks out or requests a payment link → Admin sees the lead, visit source, cart and order','["Catalogue: hero slides, category tiles, 500 generated SKUs with pagination, scroll-snap rails, Ctrl/Cmd+K search", "Pricing modes: retail and wholesale pricing toggle; saved products and saved-only view", "Cart & checkout: quantity controls, persistent per-phone cart, checkout and direct payment-link demo, coupon field", "QR & sharing: generate and read QR links for product / category / mode; printable spec sheet per product", "Lead gate & admin: phone-number gate, lazy-loaded admin panel with leads, visits, favourites, carts and orders", "Docs: PRD and technical requirements, API contract v1, deployment runbook, 500-product seed CSV"]'::jsonb,'["React", "Vite", "Framer Motion", "qrcode", "localStorage store", "Supabase schema (planned)"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,600) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('blinksai-growth-site','Growth agency website & lead engine',NULL,'Growth engineering agency · Nashik','Websites','Marketing & software services','Visitors browse BlinksAI''s platform pages, automation services (WhatsApp, AI voice IVR, workflow, social media), digital marketing and work portfolio, try an ROI calculator and submit a get-started lead form with TRAI consent. The owner gets one content file driving nav, footer, contact and llms.txt, a /api/lead endpoint that validates and logs leads, analytics, sitemap and robots.','Main workflow: Visitor lands on the 3D hero homepage → Picks a path (build / automate / grow) → Opens a platform or service page → Fills the Get Started lead form with consent → POST /api/lead validates and logs the lead for the queue','["Home: 3D operations board hero, scroll-driven loop engine, path selector, pricing, ROI calculator, FAQ", "Platforms: index plus 8 platform pages ([slug]) with 3D module stacks and product screenshots", "Automate: WhatsApp automation, AI voice IVR, workflow automation and social media automation pages", "Grow / Work: digital marketing page and filterable work portfolio", "Get started: lead form with TRAI consent posting to /api/lead; conversation drawer and mobile CTA bar", "Site plumbing: gtag analytics, sitemap, robots, llms.txt, single content.ts for all copy"]'::jsonb,'["Next.js 16", "React 19", "Tailwind v4", "React Three Fiber", "GSAP", "Zustand"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,610) ON CONFLICT ("slug") DO NOTHING;
