INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('visa-recruitment-manager','Visa & recruitment management system',NULL,'Overseas recruitment agency','ERP / CRM','Immigration & recruitment','A single admin records each visa applicant as a client with an auto-generated application ID, passport, agency / foreign office, agent, job category, visa type, status and advance / due payments. The owner gets a dashboard with status and monthly charts, follow-up dates, payment reports, search, Excel export and JSON backup / restore.','Main workflow: Admin logs in → Adds a client with passport, agency, job category, visa type and advance payment → Status moves pending → approval pending → approved → visa issued / rejected → Follow-up dates and due payments tracked → Reports, Excel export and backup','["Dashboard: client counts by status, advance / due / total payment totals, status and monthly trend charts", "Clients / Applications: add, edit, delete, search by name, passport, agency, country; filter by status", "Agents and Agency / Foreign Office: CRUD with cases per agency (pending, approved, completed)", "Job categories and Visa types: master lists used in the client form", "Payments and Follow Up: advance + due = total, balance, payment reports with filters, follow-up list", "Reports, Search, Export to Excel, Backup (JSON), Settings: admin utilities behind single login"]'::jsonb,'["Next.js 14", "Supabase", "Tailwind", "Recharts", "XLSX"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,620) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('slotnova-visa-appointments','Visa appointment management system',NULL,'Visa services agency','Management systems','Immigration services','Staff add visa applicants (with passport upload and MRZ parsing), monitor simulated VFS slot availability per country, centre and visa type, and walk each booking through a human checklist until it is confirmed. The owner gets dashboard counters, confirmed bookings, payments, activity logs, reports, notifications, users and settings. Slot checks are simulation-only; CAPTCHA and OTP steps stay manual on the official portal.','Main workflow: Staff adds an applicant and uploads the passport (MRZ parsed into fields) → Applicant enters slot monitoring for country / centre / visa type → Simulated availability tick flags a slot → Staff advances the human booking checklist on the official portal → Booking confirmed; logs and reports update','["Dashboard: stat cards and charts for applicants, monitoring and bookings", "Applicants / Add Applicant: filters (country, visa type, centre, status), view / edit dialogs, passport upload", "Passport Reader: ICAO 9303 MRZ parser with check-digit validation filling applicant fields", "Slot Monitoring: pause / resume per applicant, demo availability simulation", "Bookings: booking dialog with step-by-step human checklist; confirmed bookings list", "Payments, Countries, Visa Types, Visa Centres, Logs, Reports, Notifications, Users, Settings"]'::jsonb,'["React (Vite)", "Express", "SQLite (node:sqlite)", "Node 22"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,630) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('safar-ai-travel-assistant','AI travel lead assistant','Shera Travels','Travel agency · Kashmir','AI applications','Travel','Agency staff watch WhatsApp leads being qualified by an AI concierge in a multilingual inbox, generate a day-by-day itinerary from a short brief, and switch automation rules (new-inquiry concierge, itinerary delivery check, trip reminders, cold-lead revival) on or off. The owner gets a Node API for leads, conversations and itinerary generation (Gemini with a deterministic fallback) and a worker with scheduling, retries, opt-out suppression and language-aware templates.','Main workflow: Inbound WhatsApp message creates a lead → AI qualifies it and captures preferences → Staff generates a personalised itinerary in Journey Builder → Automation rules schedule follow-ups and reminders → Sensitive conversations are handed to a human','["Overview: live automation run card, metrics (conversations, qualified leads, journeys, pipeline), live chats", "AI Inbox: multilingual conversation list and chat sending through the product API", "Journey Builder: destination / days / travellers / style form generating a day-wise itinerary", "Automations: rules with trigger, runs, success rate and enable toggle (PATCH /api/automations)", "API: /api/leads, /api/conversations/:id/messages, /api/itineraries/generate, bearer auth, rate limit", "Worker: simulated or Baileys WhatsApp adapter, idempotency, retry / backoff, opt-out suppression"]'::jsonb,'["React 19 (Vite)", "Node API", "Gemini (optional)", "Baileys (optional)", "Supabase migrations with RLS"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,640) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('shera-travels-crm','Travel agency CRM & itinerary maker','Shera Travels','Travel agency · Kashmir','ERP / CRM','Travel','Staff build tour packages day by day (info, pricing, photos, terms), preview and export them as PDF, and send quotes to customers on WhatsApp. Leads move through stages to bookings with a public booking-form link; the owner also manages invoices, hotels, cabs, income, expenses, website content and packages, newsletter subscribers, users with module access and audit logs.','Main workflow: Lead captured and moved through stages → Staff builds a day-wise package in the editor and sends a WhatsApp quote → Customer fills the public booking form via token link → Booking detail tracked with invoice → Income, expenses and audit logs update','["Home: package cards, lead stages overview, Send Quote on WhatsApp modal", "Editor: day builder with day cards, Info / Pricing / Photos / T&C tabs, preview modal and PDF export", "CRM: Dashboard, Leads, Bookings and Booking detail with edit modal; public /booking/form/:token", "Invoices: list plus invoice generator (new / edit)", "Resources: Hotels, Cabs, Photos, Income, Expenses", "Admin: Users with module access, Website content, Website packages, Newsletter subscribers, Audit logs"]'::jsonb,'["React 19 (Vite)", "Supabase", "React Router 7", "jsPDF + html2canvas", "Recharts", "Razorpay"]'::jsonb,'https://sheratravels-orcin.vercel.app','[]'::jsonb,'live',false,true,650) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
