INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('maheshwari-realcon-site','Real estate listings website','Maheshwari Realcon Pvt. Ltd.','Real estate agency · Patna','Websites','Real estate','Visitors browse residential, commercial, industrial and land listings around Patna on buy, rent, commercial and projects pages, open a property detail with photos, amenities, nearby places, agent contact and RERA number, and enquire through the contact section or WhatsApp button. Listings live in a typed data file the owner edits; there is no backend.','Main workflow: Visitor lands on hero and featured properties → Picks Buy / Rent / Commercial / Projects → Opens a property detail → Calls the agent or taps WhatsApp → Submits a contact enquiry','["Home: hero, property types, featured properties carousel, why choose us, testimonials, contact section", "Properties / Buy / Rent / Commercial / Projects: listing pages driven by lib/properties.ts", "Property detail [id]: price, area, floor, facing, furnishing, images, amenities, nearby places, agent, RERA", "About and Privacy policy pages", "Floating WhatsApp button and footer with Patna locality links"]'::jsonb,'["Next.js 16", "React 19", "Tailwind v4", "Framer Motion", "react-slick"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,660) ON CONFLICT ("slug") DO NOTHING;
