INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('dcw-call-routing','Call routing & tracking dashboard','Distance Courses Wala (DCW)','Distance education consultancy','Custom software','Education','Customers call one business number and the system rings agents in priority order with ring timeouts, failover, office-hours fallback and an automatic callback for every missed call. Managers watch live routing, review each call''s attempt timeline with notes and recordings, manage agents and routing rules, work the callbacks board and export agent reports; access is role-based (super admin, manager, agent, auditor) with audit logs.','Main workflow: Inbound call hits the telephony webhook → Routing engine rings agents by priority with timeout and failover → Answered call logged with attempt timeline; missed call creates a callback → Agent adds notes and click-to-calls back → Reports and audit log update','["Dashboard: KPI cards, period selector, charts, live routing panel, agent status, callbacks, recent calls", "Calls / Call detail: filters, pagination, attempt-by-attempt timeline, notes, recording playback, CSV export", "Agents: CRUD, drag-and-drop priority, shifts, availability, per-agent ring timeout", "Routing: builder for ring order, timeouts, eligibility, office hours / holidays and fallback", "Callbacks: pending / overdue / assigned / resolved board with click-to-call outbound modal", "Reports, Settings, Audit: agent performance with CSV export, org settings, audit log; RLS-enforced roles"]'::jsonb,'["Next.js 16", "Supabase (Postgres, Auth, RLS)", "Tailwind v4", "Recharts", "Zod", "Exotel / Buzzdial / MyOperator adapters"]'::jsonb,'https://dcw-ivr.vercel.app','[]'::jsonb,'live',false,true,670) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
