INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('soil-organic-site','Agri products website with CMS','Sheevar Organic Industrial Limited (SOIL)','Organic agri-inputs company · Bihar','Websites','Agriculture','Farmers and dealers browse SOIL''s bio-fertilizer and organic input products, open product details, view the gallery and submit dealer / distributor or contact enquiries. The owner edits site text and images from a password-protected /admin panel that writes site-content.json and uploads to GitHub through a Netlify function, which triggers a redeploy.','Main workflow: Visitor lands on the video-hero home → Browses the products list → Opens a product detail → Submits a dealer / distributor or contact enquiry → Admin updates content in /admin; Netlify function commits to GitHub and the site redeploys','["Home: video hero, CMS-bound sections (data-cms attributes), about and solutions blocks", "Products: products-list.js and product-detail.js rendering data/products.json", "Dealer / Distributor: enquiry page for distribution partners", "Gallery, About, Contact pages; robots.txt and sitemap.xml", "Admin: password login, content editor saving data/site-content.json and images via a Netlify function"]'::jsonb,'["HTML/CSS/JS", "Netlify Functions", "GitHub contents API", "JSON content files"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,690) ON CONFLICT ("slug") DO NOTHING;
