INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('meera-prakash-admission-crm','Admission consultancy website + CRM','Meera Prakash Education Center','Admission consultancy · Patna','ERP / CRM','Education','Students browse courses and the Bihar Student Credit Card page, submit an admission enquiry (which creates a CRM lead, emails the team and builds a WhatsApp link) and pay fees through Razorpay. Staff run leads, student records, fees, dispatch, HRMS with payroll and salary slips, finance, associates with wallets, incentives and targets; students and associates each get their own portal.','Main workflow: Website enquiry or admission form creates a lead → Telecaller / counsellor works and converts the lead to a student → Fees collected and receipt / invoice issued → Documents dispatched; student tracks it in the portal → Attendance, payroll slips and finance reports update','["Website: Home, Courses, Bihar Student Credit Card, Admission form, Razorpay payment, About, Contact", "CRM Leads & Students: list, import, detail timeline, convert; student records with docs, exams, fees, dispatch", "Finance & Fees: income, expenses, centre fee, fee plan builder, wallets, incentives, targets, analytics", "HRMS: employees, attendance with auto punch-out cron, payroll generation, salary slip email, advances", "Associates: approval, recharge approval, notifications; portal with admissions, students, dispatch, tasks", "Student portal: dashboard, admission, accounts, dispatch, materials, mentorship, refer, support"]'::jsonb,'["Next.js 16", "Supabase (Postgres, Auth)", "Razorpay", "Nodemailer", "react-pdf", "Tailwind v4 + shadcn"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,700) ON CONFLICT ("slug") DO NOTHING;
