INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('admission-path4u-site','College discovery website with CMS','Admission Path4u','Education consultancy','Websites','Education','Students browse colleges, courses, exams, services and blogs, open college detail pages and send enquiries through contact forms and a lead popup. An admin logs in to manage colleges, exams, blogs, services, homepage hero and banners, the about page and incoming leads, with sitemap, robots and a PWA manifest generated for SEO.','Main workflow: Visitor lands on home with banner carousel → Filters colleges / courses or reads exam and blog pages → Submits the lead popup or contact form → Admin reviews leads → Admin updates colleges, exams, blogs and homepage content','["Home: banner carousel, course filter section, college directory, services, blogs, lead popup, WhatsApp button", "Colleges / Courses / Exams / Services / Blogs: list and [slug] detail pages with filters and search", "Contact: form and dialog creating leads through server actions", "Admin: JWT login, dashboard, leads manager, college / exam / blog / service forms with image upload", "Admin content: homepage hero editor, about editor, settings; seed route", "SEO: sitemap, robots, manifest and a central seo.ts"]'::jsonb,'["Next.js 16", "Supabase", "Mongoose models", "Tailwind v4 + Radix", "react-hook-form + Zod", "JWT auth"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,710) ON CONFLICT ("slug") DO NOTHING;
