INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('falcon-plus-bags-store','Bags & luggage online store','Falcon Plus Bags','Bag & luggage brand · India','E-commerce','Retail','Shoppers browse backpacks, duffels and luggage by category or collection, open a product with colour variants, add it to the cart, check out and land on an order-success page; corporate buyers submit a gifting enquiry. The admin logs in to manage products with multi-image upload, homepage banners and corporate leads from a dashboard.','Main workflow: Shopper browses a category page → Opens product [slug] and picks a colour → Adds to cart and checks out → Order success page; account page → Admin manages products, banners and corporate leads','["Storefront: announcement bar, hero, category pages (backpacks, duffels, luggage, collection), our story", "Product detail: images per colour, add-to-cart button, mini cart drawer", "Cart / Checkout / Order success; Account page with Supabase auth callback", "Corporate gifting: enquiry form stored as corporate leads", "Admin: login, dashboard, products list / new / edit with image and multi-image upload, banners, leads", "Newsletter and contact forms"]'::jsonb,'["Next.js 14", "Supabase", "Zustand cart", "Tailwind 3", "JSON seed scripts"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,720) ON CONFLICT ("slug") DO NOTHING;
