INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('admission-path4u-crm','Education consultancy CRM & HRMS','Admission Path4U','Education consultancy','ERP / CRM','Education','Telecallers and admins capture and bulk-import leads, track activities and transfers, and convert leads to students; the backend team then maintains each student''s document checklist, exam tracker, fee tracker and printable invoice. The owner gets finance (income and expenses with monthly summary), HRMS (employees, attendance punch, payroll with PDF salary slips), litigation, incentives, performance and analytics, plus an invoice tool with GST lookup and PDF ticket extraction.','Main workflow: Lead added or bulk-imported → Lead worked with timeline, transfer and filters → Converted to a student record → Documents, exams and fees tracked; invoice printed → Payroll generated and finance / analytics update','["Leads: table with filters and column preferences, bulk import, lead form, timeline, transfer and convert modals", "Students (backend): student form / record, document checklist, exam tracker, fee tracker, invoice PDF", "Finance: income and expense tables, monthly summary; Incentive and Performance pages for the lead role", "HRMS: employee table, attendance grid and punch client, payroll month selector / table, salary slip PDF", "Settings: users, departments, courses, sessions, form fields, columns; Litigation; Analytics", "Invoice module: GST lookup and PDF ticket extraction routes, invoice preview and dashboard"]'::jsonb,'["Next.js 16", "Supabase (Postgres, SSR auth)", "Tailwind v4 + shadcn", "react-pdf / jsPDF", "Zustand", "pdf-parse"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,730) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('vidya-education-group-site','Education group website','Vidya Educational Services','Coaching & library group · Patna','Websites','Education','Students explore the group''s four study-library tiers with a seat booking summary, online and offline coaching courses and faculty, admission consultancy verticals (tech, management / law, medical), the tiffin service and hostel, and send enquiries through a lead form. All content lives in data files the owner edits; there is a simple dashboard page and no backend.','Main workflow: Visitor lands on the bilingual home → Picks Library, Coaching, Consultancy, Tiffin or Hostel → Opens a library wing or course detail → Reviews the booking summary → Submits the lead form or calls','["Home / About / Contact: brand data from site.js with hours, phones and head office", "Library: hub plus Topper''s, Digital, Premium and Luxury wings and a booking summary page", "Coaching: hub, online classes, offline centre, course detail [slug], faculty", "Consultancy: gateway, admission hub, tech, management / law and medical verticals", "Tiffin service, Hostel, Dashboard and 404 pages; reusable lead form component"]'::jsonb,'["React 18 (Vite)", "React Router 6", "Tailwind 3", "Framer Motion"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,740) ON CONFLICT ("slug") DO NOTHING;
