INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('sellerhub-poster-listing-tool','AI product poster & listing tool',NULL,'Product seller / D2C brand','AI applications','E-commerce marketing','A seller adds products with images and a brand colour, designs a promotional poster on a canvas with AI-written taglines, captions, offers and hashtags tuned per platform, then schedules posts to Instagram / Facebook and pushes listings to Amazon and custom marketplaces. The dashboard shows products, scheduled and published posts and live listings, and a cron publishes due posts.','Main workflow: Seller adds a product (image upload, price, MRP, stock) → Generates a poster with Claude-written copy in the Poster Designer → Schedules the post for chosen social platforms → Lists the product on e-commerce platforms → Cron posts due items; dashboard shows statuses','["Dashboard: counts of products, scheduled posts, published posts, live listings and recent posts", "Products: CRUD with image upload, category, price / MRP, brand colour, stock", "Poster: Fabric.js designer with colour picker, style toggle and AI copy (tagline, caption, offer, hashtags)", "Scheduler: pick product, poster, caption, platforms and time; status pending / posted", "Listings: push products to Amazon SP-API and custom e-com platforms with per-platform status / errors", "Settings: platform API keys and custom platforms; daily cron route and node-cron scheduler"]'::jsonb,'["Next.js 14", "Prisma (SQLite)", "Anthropic Claude SDK", "Fabric.js", "Meta Graph API", "Amazon SP-API"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,760) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('shera-travels-booking-crm','Travel booking site & itinerary CRM','Shera Travels','Kashmir tour operator · Srinagar','ERP / CRM','Travel & tourism','Travellers browse Kashmir destinations and packages, search by duration and guest count, and book a tour by paying a 20% advance through Razorpay. The owner gets a separate CRM at /crm with leads, bookings, payments, an itinerary maker and settings, plus email notifications for every new lead, booking and payment via Resend.','Main workflow: Visitor searches packages by destination, days and guests → Fills booking form (name, phone, date, guests) → Pays 20% advance via Razorpay → Booking and payment rows saved to Supabase, owner emailed → Staff build and send the itinerary and invoice from the CRM','["Home / Packages / Destinations: searchable Kashmir packages with slider, stats and WhatsApp contact", "Booking modal: 3-step form \u2192 Razorpay advance payment \u2192 success with payment reference", "Email API: Resend templates for new lead, new booking, payment received, itinerary and invoice", "CRM (/crm): Dashboard, Leads, Bookings & Revenue, Payments, Packages, Itinerary Maker, Settings & Admin", "Itinerary maker: day-wise tour builder with hotel/houseboat stays, duplicate and send by email"]'::jsonb,'["React 19", "Vite", "React Router", "Supabase", "Razorpay", "Resend", "Vercel"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,770) ON CONFLICT ("slug") DO NOTHING;
