INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('22yard-betting-landing','Cricket betting promo landing page','22Yard','Online betting promoter · India','Websites','Gaming','A phone-width promotional landing page styled like a betting app: live-looking match cards, sport tiles, offer strips, a sign-up bonus banner and a list of partner betting sites, with every call to action going to a WhatsApp link. There is no backend; the owner edits content directly in the components.','Main workflow: Visitor lands on the ticker + promo banner → Browses match cards and sport categories → Sees offers, stats and partner sites → Taps the sticky WhatsApp button to get an ID','["App shell: 430px mobile frame with ticker banner, header, search bar and bottom nav", "Match cards: today''s match cards with teams, scores and ''upcoming'' tags", "Sports list and sport cards: cricket, football and casino-style categories", "Offers grid and promo banner: sign-up bonus and urgency countdown sections", "Available sites: list of partner betting domains as outbound links", "WhatsApp sticky button: wa.link deep link on every screen"]'::jsonb,'["Next.js 16", "React 19", "Tailwind 4", "shadcn/ui"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,false,780) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('edumatch-consultancy-crm','Education consultancy CRM & HRMS','EduMatch Overseas','Study-abroad consultancy · India','ERP / CRM','Education','Counsellors log and import leads, track activity timelines, transfer leads between staff and convert them into enrolled students with fee, document and exam tracking. The owner gets finance (income/expenses), an HR module with attendance, payroll and salary-slip PDFs, incentive and performance views, a litigation/debt tracker and analytics, with roles, courses, sessions and form fields configurable in settings.','Main workflow: Lead captured or bulk-imported from Excel → Counsellor follows up and logs activities → Lead converted to student with course and session → Fees recorded, documents and exams tracked, invoice printed → Payroll, incentives and analytics update for management','["Leads: filterable table, lead form, timeline, bulk Excel import, transfer and convert-to-student modals", "Students (backend): student record with fee tracker, document checklist, exam tracker and PDF invoice", "Finance: income and expense tables with monthly summary", "HRMS: employee list, attendance grid, payroll generation and salary slip PDF, performance", "Litigation: debt and litigation cases per student with payment history", "Settings: users and roles, departments, courses/sub-courses, sessions, form fields, table columns"]'::jsonb,'["Next.js 16", "Supabase", "Postgres (SQL migrations)", "Tailwind 4", "shadcn/ui", "react-pdf"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,790) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('gmb-review-manager','Google Business review-management SaaS','Blinks SEO','Local SEO agency · in-house product','SaaS','Marketing','Agencies sign in with Google, sync their clients'' Google Business Profiles (or add businesses manually), attach target keywords and generate QR codes that send customers to a review landing page with AI-written review suggestions. The owner gets AI reply drafts for reviews, saved text templates and Free/Starter/Pro/Agency plans billed through Razorpay, available as both a web app and an Expo mobile app.','Main workflow: Agency logs in with Google → Syncs GMB businesses → Adds keywords per business → Generates a QR code → Customer scans it, gets AI-suggested review text and posts the review → Agency replies with AI-drafted responses','["Businesses: GMB sync via Google Business Profile API or manual add, business detail screen", "Keywords: add, edit and delete target keywords per business", "QR codes: generate per-business QR, public /qr/:code landing page with scan counter", "AI review: Gemini-generated review text, reply drafts and reply templates, saved per business", "Plans: Free/Starter/Pro/Agency tiers with Razorpay order creation and payment verification", "Mobile app: Expo screens for dashboard, businesses, reviews, keywords, QR and profile"]'::jsonb,'["Express", "Supabase", "Google Business Profile API", "Gemini API", "Razorpay", "React + Vite", "Expo / React Native"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,800) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('legal-registration-services-site','Legal registration services website','dlegaltech','Online legal consultancy · India','Websites','Legal services','Visitors browse NGO, business and compliance registration services (NGO, 12A/80G, Section 8, FCRA, GST and more), each with price, timeline, documents, process steps and FAQs, and submit a lead or newsletter form. The owner gets SEO-ready service and location pages, a blog, and a client dashboard mock that shows order stages from Applied to Approved.','Main workflow: Visitor lands on a service or city page → Reads price, documents and process → Submits the lead form or taps WhatsApp → Client later tracks order stages on the dashboard','["Services: catalogue plus /services/[slug] pages with price, timeline, benefits, documents, process and FAQs", "Locations: /locations/[slug] city landing pages for local SEO", "Blog: listing and article pages", "Lead form and newsletter form with zod validation; sticky CTA and WhatsApp widget", "Client dashboard: order list with 4-stage progress (mock data)", "SEO: sitemap, robots and JSON-LD organisation metadata"]'::jsonb,'["Next.js 16", "Tailwind 4", "react-hook-form + zod", "Framer Motion", "Netlify"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,810) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('structure-square-website','Architecture firm website with admin','Structure Square Home Solutions','Architecture & construction firm · Patna','Websites','Construction','Visitors explore architecture, construction, interior and real-estate service pages, a portfolio and careers, and request a quote through a floating form that captures project type, budget and city. The owner logs into an admin panel to see contact and career leads, edit page content and stats, upload images, manage the team and settings, all stored in Supabase.','Main workflow: Visitor browses services and portfolio → Submits quote or career form → Lead stored in Supabase → Admin reviews leads → Admin updates content, images and team from the panel','["Public site: home, about, portfolio, careers, contact and four service pages", "Floating quote form: project type, budget range and city selectors", "Admin leads: contact inquiries and career applications with totals and type filter", "Admin content: edit page sections, stats (EST year, projects, team size) and brochure", "Admin images, team and settings pages behind a login API", "Reviews API route plus sitemap and robots"]'::jsonb,'["Next.js 16", "Supabase", "Tailwind 3", "Framer Motion", "React Three Fiber", "Netlify"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,820) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('blinks-ai-strategy-landing','Marketing agency lead-gen landing page','Blinks AI','Digital marketing agency · in-house','Websites','Marketing','A single-page site that pitches a free 60-minute growth strategy call: pain points, what the session includes, how it works, founder bio, testimonials, pricing and FAQ, with ''Book a Call'' and WhatsApp buttons. All copy lives in one constants file so the owner can change the offer without touching components.','Main workflow: Visitor reads the hero and pain points → Sees what the session includes → Reads how it works and testimonials → Books a call or messages on WhatsApp','["Hero: two-line headline, primary/secondary CTAs and social-proof strip", "Pain points and ''What you get'' sections driven by lib/constants.ts", "How it works: 3-step apply \u2192 call \u2192 roadmap", "About founder, testimonials, pricing and FAQ accordion", "Book-call CTA and WhatsApp CTA components"]'::jsonb,'["Next.js 16", "React 19", "Tailwind 4", "Framer Motion"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,830) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('admission-pramarsh-site','Admission consultancy website','Admission Pramarsh','Education consultancy · Patna','Websites','Education','Students search universities and courses, open course-category pages (medical, engineering, management and more) with eligibility criteria, branches and top colleges, and request a callback by entering a phone number. The owner gets a marketing site with partners, stats, testimonials, articles/webinars and contact pages.','Main workflow: Visitor searches a course or university → Opens /:type/:category course page → Reviews eligibility and colleges → Submits callback number or contact form','["Home: hero search, services, popular courses, partners, stats, testimonials, articles & webinars", "Course detail: overview, eligibility table, available branches and popular colleges per category", "Callback banner: phone-number capture strip", "About and Contact pages with top bar contact details"]'::jsonb,'["React 18", "Vite", "React Router", "Netlify"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,840) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('admission-aasharay-site','Admission consultancy website','Admission Aasharay','Education consultancy · Patna','Websites','Education','Students browse course streams (medical, engineering, management, law, paramedical, polytechnic), top colleges, study-abroad and Bihar Student Credit Card pages, and apply for a course through a modal form or the auto-popup. The owner gets a multi-page marketing site with hero slider, achievements, photo and video galleries, testimonials and a map.','Main workflow: Visitor lands on hero slider → Picks a course stream page → Reviews colleges and services → Fills the apply modal or popup with name and phone → Consultancy follows up','["Home: hero slider, marquee, feature cards, achievements, college list, testimonials, map", "Stream pages: medical, engineering, management, law, paramedical, polytechnic, top colleges", "Study abroad and Bihar Student Credit Card information pages", "Course apply modal and timed auto-popup lead forms", "Photo and video galleries"]'::jsonb,'["Next.js 16", "React 19", "Tailwind 4", "Netlify"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,850) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('betup365-landing','Betting ID landing page','BetUp365','Online betting promoter · India','Websites','Gaming','A one-file landing page that promotes cricket betting IDs: feature cards (instant ID, cricket focus, easy payments), a three-step ''click WhatsApp, complete KYC, start playing'' section and WhatsApp buttons. No backend; the owner edits the single HTML file.','Main workflow: Visitor reads the offer → Sees the 3-step process → Taps WhatsApp → Completes KYC with the operator off-site','["Hero with title and description aimed at cricket bettors", "Feature cards: Instant ID, Cricket Focused, Easy Payments", "How it works: 1) Click WhatsApp 2) Complete KYC 3) Start Playing", "WhatsApp call-to-action with +91 number prompt"]'::jsonb,'["HTML", "CSS", "JavaScript"]'::jsonb,'https://pintu-ochre.vercel.app','[]'::jsonb,'live',false,false,860) ON CONFLICT ("slug") DO NOTHING;
--> statement-breakpoint
INSERT INTO "portfolio_media" ("project_id", "content_type", "src", "caption", "sort_order") SELECT "id", 'image/webp', '/work-shots/betup365-landing-1.webp', 'Home', 0 FROM "portfolio_projects" WHERE "slug" = 'betup365-landing' AND NOT EXISTS (SELECT 1 FROM "portfolio_media" WHERE "project_id" = "portfolio_projects"."id");
