INSERT INTO "portfolio_projects" ("slug","name","client_name","client_label","category","industry","summary","description","features","tech_stack","demo_url","demo_logins","demo_status","embeddable","published","sort_order") VALUES ('gym-membership-system','Gym membership & attendance system','The A1 Gym','Gym · Barbigha, Bihar','Management systems','Fitness','New members join through a public /join link, get a QR member card and check in by scanning it at the desk. Staff log in to manage members, plans, billing with GST invoices and renewals, view attendance logs and calendars, see dashboard charts and export reports; Supabase functions send renewal and attendance reminders over WhatsApp and email, and Razorpay is wired for payments.','Main workflow: Member registers via /join/[gymId] → Staff assign a plan and record payment → Invoice generated (INV-YYMM-0001) → Member checks in by QR scan → Renewal reminders go out and reports update','["Members: list, new member form with Aadhaar upload, detail with attendance calendar, edit", "Attendance: QR scanner page, manual check-in, attendance log", "Billing: payments with GST, invoice PDF per payment, renewals-due view with overdue and potential revenue", "Plans: duration-based membership plans with amounts and features", "Dashboard and reports: membership gauge, line chart, activity donut, period filters, export", "Public: /join registration page and /card/[code] member card; PWA install support"]'::jsonb,'["Next.js 14", "Supabase", "Razorpay", "Resend", "Interakt WhatsApp", "ApexCharts", "next-pwa"]'::jsonb,NULL,'[]'::jsonb,'coming_soon',false,true,870) ON CONFLICT ("slug") DO NOTHING;
